MC.registerPack({"id":"spiderham","cards":[{"id":"30001a","name":"스파이더햄","en":"* Spider-Ham","type":"hero","enc":false,"unique":true,"hp":12,"atk":1,"thw":2,"def":1,"hs":5,"tr":["CARTOON","WEB-WARRIOR"],"traits":["만화","웹 워리어"],"text":"스파이더햄에게 놓인 각 툰 카운터는 [wild] 자원인 것처럼 소모할 수 있습니다.\n<i>스파이더 난센스</i> — <b>반응</b>: 스파이더햄이 피해를 입은 후, 그에게 툰 카운터를 1만큼 놓습니다."},{"id":"30001b","name":"피터 포커","en":"* Peter Porker","type":"alter","enc":false,"unique":true,"hp":12,"rec":5,"hs":6,"tr":["CARTOON","CIVILIAN"],"traits":["만화","시민"],"text":"<i>만화의 힘</i> — <b>반응</b>: 당신이 기본 회복을 한 후, 피터 포커에게 툰 카운터를 1만큼 놓습니다."},{"id":"30002","name":"캡틴 아메리캣","en":"* Captain Americat","type":"ally","enc":false,"sub":"스티브 무저","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":3,"res":"G","cls":"Hero","tr":["CARTOON"],"traits":["만화"],"text":"<b>반응</b>: 캡틴 아메리캣이 플레이 영역에 들어온 후, 누군가와 하이파이브를 합니다. 당신의 아이덴티티에 툰 카운터를 1만큼 놓고, 당신의 버린 더미에서 스파이더햄 카드 1장을 당신의 덱에 섞어 넣습니다."},{"id":"30003","name":"과장 연기","en":"Ham It Up","type":"event","enc":false,"unique":false,"cost":0,"res":"B","cls":"Hero","tr":["CARTOON","THWART"],"traits":["만화","저지"],"text":"<b>히어로 행동</b><i>(저지)</i>: 스파이더햄에게 놓인 툰 카운터마다 음모 하나에서 위협을 1만큼 제거합니다."},{"id":"30004","name":"헛소리!","en":"Hogwashed","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Hero","tr":["CARTOON"],"traits":["만화"],"text":"<b>히어로 행동</b>: 스파이더햄에게서 툰 카운터를 1만큼 제거 → 이 카드의 플레이버 텍스트를 큰 소리로 읽음. 하수인 하나에게 피해 5점을 입히거나 부가 음모 하나에서 위협을 5만큼 제거하는 것 중 하나를 선택."},{"id":"30005","name":"\"어림없지!\"","en":"\"I Don't Think So!\"","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Hero","tr":["CARTOON"],"traits":["만화"],"text":"<b>히어로 난입</b>: 당신이 조우 덱에서 카드를 공개할 때, 스파이더햄에게서 툰 카운터를 1만큼 제거 → 최고의 스파이더햄 목소리로 \"어림없지!\"라고 외침. 그 카드의 효과를 무효화하고 버림."},{"id":"30006","name":"성질 고약한 돼지","en":"Petulant Pig","type":"event","enc":false,"unique":false,"cost":0,"res":"B","cls":"Hero","tr":["CARTOON"],"traits":["만화"],"text":"<b>히어로 행동</b>: 빌런에게 혀를 내밉니다. 빌런이 당신을 공격합니다. 카드 3장을 뽑습니다."},{"id":"30007","name":"거미줄 날아돼지","en":"Swinging Web Pig","type":"event","enc":false,"unique":false,"cost":3,"res":"Y","cls":"Hero","tr":["CARTOON","ATTACK"],"traits":["만화","공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 6점을 입힙니다. 그 적을 혼란에 빠뜨립니다."},{"id":"30008","name":"데일리 비글","en":"* The Daily Beagle","type":"support","enc":false,"unique":true,"cost":2,"res":"B","cls":"Hero","tr":["CARTOON","LOCATION"],"traits":["만화","장소"],"text":"<b>일상 행동</b>: 데일리 비글을 소진 → 피터 포커에게 툰 카운터를 1만큼 놓음."},{"id":"30009","name":"만화 물리학","en":"Cartoon Physics","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"R","cls":"Hero","tr":["CARTOON","SUPERPOWER"],"traits":["만화","슈퍼파워"],"text":"<b>난입</b>: 당신의 아이덴티티가 피해를 입으려 할 때, 이 카드를 버림 → 몸을 흔들흔들 흔들고 그 피해 중 1점을 제외한 나머지를 모두 방지."},{"id":"30010","name":"거대한 나무망치","en":"Huge Wooden Hammer","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"R","cls":"Hero","tr":["CARTOON","WEAPON"],"traits":["만화","무기"],"text":"스파이더햄은 공격 +1을 받습니다.\n<b>히어로 난입</b>: 스파이더햄이 기본 공격을 할 때, 거대한 나무망치를 소진하고 스파이더햄에게서 툰 카운터를 1만큼 제거 → 스파이더햄은 그 공격에 공격 +2를 받음. 그 공격은 압살을 얻음."},{"id":"30011","name":"유기 거미줄","en":"Organic Webbing","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"B","cls":"Hero","tr":["CARTOON","SUPERPOWER"],"traits":["만화","슈퍼파워"],"text":"스파이더햄은 저지 +1을 받습니다.\n<b>히어로 행동</b>: 유기 거미줄을 소진하고 스파이더햄에게서 툰 카운터를 1만큼 제거 → 스파이더햄을 준비. 그는 페이즈의 끝까지 [[공중]] 특성을 얻음."},{"id":"30012","name":"레이디 스파이더","en":"* Lady Spider","type":"ally","enc":false,"sub":"메이 라일리","unique":true,"hp":4,"atk":2,"atkStar":true,"atkCons":2,"thw":2,"thwStar":true,"thwCons":2,"cost":4,"res":"B","cls":"Justice","tr":["WEB-WARRIOR"],"traits":["웹 워리어"],"text":"[star] <b>반응</b>: 레이디 스파이더가 저지해 음모에서 위협을 제거한 후, 당신이 다른 [[웹 워리어]] 카드를 조종하고 있다면, 다른 음모 하나에서 같은 양의 위협을 제거합니다.","star":true},{"id":"30013","name":"스파이더맨","en":"* Spider-Man","type":"ally","enc":false,"sub":"파비트르 프라바카르","unique":true,"hp":3,"atk":1,"atkStar":true,"thw":1,"thwStar":true,"cost":3,"res":"Y","cls":"Justice","tr":["WEB-WARRIOR"],"traits":["웹 워리어"],"text":"<b>반응</b>: 스파이더맨이 플레이 영역에 들어온 후, 당신이 조종하는 [[웹 워리어]] 카드마다(스파이더맨 포함) 음모 하나에서 위협을 1만큼 제거합니다."},{"id":"30014","name":"열세 만회","en":"Even the Odds","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","req":"Y","cls":"Justice","tr":["THWART"],"traits":["저지"],"text":"요구 조건([energy]).\n<b>히어로 행동</b><i>(저지)</i>: 각 부가 음모에서 위협을 1[per_hero]만큼 제거합니다. 이렇게 격파된 부가 음모마다 빌런에게 피해 1점을 입힙니다."},{"id":"30015","name":"큰 힘에는 큰 책임이 따른다","en":"Great Responsibility","type":"event","enc":false,"unique":false,"cost":0,"res":"B","cls":"Justice","tr":[],"traits":[],"text":"<b>히어로 난입</b>: 음모 하나에 위협이 놓이려 할 때, 그 위협만큼 당신이 대신 피해를 입습니다.","link":"01061"},{"id":"30016","name":"화려한 등장","en":"Making an Entrance","type":"event","enc":false,"unique":false,"cost":1,"res":"R","cls":"Justice","tr":["SKILL"],"traits":["기술"],"text":"<b>히어로 난입:</b> 당신의 히어로가 기본 저지를 할 때, 그 저지에서 저지 +2를 받습니다. 그 저지가 끝난 후, 당신의 히어로가 그렇게 음모 하나에서 위협을 모두 제거했다면, 당신의 히어로가 입은 피해 2점을 치료합니다.","link":"20013"},{"id":"30017","name":"어떻게든","en":"One Way or Another","type":"event","enc":false,"unique":false,"cost":0,"res":"B","cls":"Justice","tr":[],"traits":[],"text":"라운드마다 최대 1장.\n<b>히어로 행동</b>: 조우 덱에서 부가 음모 하나를 찾습니다. 그 부가 음모를 공개 → 카드 3장을 뽑음(조우 덱을 섞습니다).","link":"22015"},{"id":"30018","name":"추적","en":"Followed","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Justice","tr":[],"maxPer":1,"traits":[],"text":"부가 음모에게 장착합니다. 음모마다 최대 1장.\n<b>난입</b>: 장착된 음모가 격파될 때, 적 하나에게 피해 4점을 입힙니다.","link":"03032"},{"id":"30019","name":"엄호 태세","en":"Overwatch","type":"upgrade","enc":false,"unique":false,"cost":0,"res":"R","cls":"Justice","tr":[],"maxPer":1,"traits":[],"text":"음모에 장착합니다. 음모마다 최대 1장.\n<b>히어로 난입</b>: 저지로 인해 장착된 음모에서 위협이 제거될 때, 이 카드를 버림 → 다른 음모 하나에서 같은 양의 위협을 제거."},{"id":"30020","name":"스칼렛 스파이더","en":"* Scarlet Spider","type":"ally","enc":false,"sub":"케인","unique":true,"hp":4,"atk":2,"atkStar":true,"thw":1,"thwStar":true,"cost":4,"res":"B","cls":"Basic","tr":["WEB-WARRIOR"],"traits":["웹 워리어"],"text":"당신이 [[웹 워리어]] 카드를 조종하고 있을 때만 플레이할 수 있습니다.\n<b>난입</b>: 당신이 조우 카드를 공개하려 할 때, 카드 유형 하나를 선언한 다음 그 카드를 봅니다. 그 카드가 선언한 유형이라면, 스칼렛 스파이더에게 피해 1점을 입히고 카드 1장을 뽑습니다."},{"id":"30021","name":"SP//dr","en":"* SP//dr","type":"ally","enc":false,"sub":"페니 파커","unique":true,"hp":2,"atk":1,"atkStar":true,"thw":2,"thwStar":true,"thwCons":2,"cost":2,"res":"Y","cls":"Basic","tr":["WEB-WARRIOR"],"traits":["웹 워리어"],"text":"당신이 [[웹 워리어]] 카드를 조종하고 있을 때만 플레이할 수 있습니다.\n<b>격파될 때</b>: SP//dr가 초과 부수적 피해를 입어 격파되었다면, SP//dr를 당신의 손에 더합니다."},{"id":"30022","name":"팀 구성 연습","en":"Team-Building Exercise","type":"support","enc":false,"unique":false,"cost":2,"res":"R","cls":"Basic","tr":[],"traits":[],"text":"<b>히어로 행동</b>: 팀 구성 연습을 소진 → 당신의 손에서 당신의 히어로와 특성을 공유하는 카드 1장을 자원 비용을 1 낮춰 플레이.","link":"12024"},{"id":"30023","name":"생명과 운명의 거미줄","en":"* Web of Life and Destiny","type":"support","enc":false,"unique":true,"cost":3,"res":"Y","cls":"Basic","tr":["LOCATION","WEB-WARRIOR"],"traits":["장소","웹 워리어"],"text":"당신의 아이덴티티가 [[웹 워리어]] 특성을 가지고 있다면 이 카드의 자원 비용을 무시합니다.\n<b>반응</b>: [[웹 워리어]] 동료가 플레이 영역을 떠난 후, 플레이어 하나를 선택 → 그 플레이어는 카드 1장을 뽑음.","link":"27023"},{"id":"30024","name":"\"핫도그 진짜 먹고 싶어!\"","en":"\"I Really Want a Hot Dog!\"","type":"obligation","enc":true,"set":"Spider-Ham","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>피터 포커 플레이어에게 이 카드를 줍니다.</b>\n당신은 일상 형태로 카드를 뒤집어도 됩니다. 다음 중 하나를 선택합니다.\n• 피터 포커를 소진하고 그에게서 툰 카운터를 1만큼 제거 → \"핫도그 진짜 먹고 싶어!\"를 게임에서 제거.\n• 당신은 기절합니다. 이미 기절 상태라면, 이 카드는 쇄도를 얻습니다. 이 의무 카드를 버립니다."},{"id":"30025","name":"사악한 함정","en":"Nefarious Trap","type":"side","enc":true,"set":"Spider-Ham Nemesis","unique":false,"boost":2,"start":3,"hazard":1,"tr":[],"traits":[],"text":"<b>격파될 때</b>: 그린 고블러가 이 음모를 격파한 플레이어를 공격합니다. 그린 고블러가 플레이 영역에 없다면, 조우 덱과 버린 조우 더미에서 그를 찾아 이 음모를 격파한 플레이어와 교전 중인 채로 플레이 영역에 내려놓습니다."},{"id":"30026","name":"그린 고블러","en":"* The Green Gobbler","type":"minion","enc":true,"set":"Spider-Ham Nemesis","unique":true,"hp":4,"atk":2,"sch":1,"boost":3,"tr":["CARTOON","CRIMINAL"],"nemesis":true,"traits":["만화","범죄자"],"text":"<b>강제 반응</b>: 그린 고블러가 당신과 교전에 돌입한 후, 당신이 조종하는 각 카드에서 카운터를 모두 버립니다.\n<i>(스파이더햄의 숙적 하수인.)</i>"},{"id":"30027","name":"고블러 글라이더","en":"Gobbler Glider","type":"attachment","enc":true,"set":"Spider-Ham Nemesis","unique":false,"boost":2,"plus":{"atk":1,"sch":1},"surge":1,"tr":[],"traits":[],"text":"쇄도.\n그린 고블러에게 장착합니다. 그럴 수 없다면, 하수인에게 장착합니다.\n장착된 하수인은 [[공중]] 특성을 얻습니다."},{"id":"30028","name":"\"이거나 먹어라!\"","en":"\"Feast on This!\"","type":"treachery","enc":true,"set":"Spider-Ham Nemesis","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 피해 2점을 입습니다. 당신은 혼란에 빠집니다. 이미 혼란에 빠져 있었다면, 이 카드는 쇄도를 얻습니다."},{"id":"30029","name":"위대한 거미줄의 전사","en":"Warrior of the Great Web","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Basic","tr":["TITLE"],"maxPer":1,"traits":["칭호"],"text":"이름에 \"스파이더\"가 들어간 캐릭터에게 장착합니다. 캐릭터마다 최대 1장.\n장착된 캐릭터는 [[웹 워리어]] 특성을 얻습니다.\n<b>반응</b>: [[웹 워리어]] 동료가 플레이 영역을 떠난 후, 장착된 캐릭터는 페이즈의 끝까지 공격 +1을 받습니다."},{"id":"30030","name":"스파이더 토템 사냥","en":"Hunting the Spider-Totems","type":"side","enc":true,"set":"The Inheritors","unique":false,"boost":3,"start":6,"tr":[],"traits":[],"text":"<b>강제 난입</b>: 빌런 페이즈가 시작될 때, 조우 덱 맨 위에서 카드 3장을 버립니다. 이렇게 버려진 각 [[인헤리터]] 하수인을 가능하다면 [[웹 워리어]] 캐릭터를 조종하는 플레이어와 교전 중인 채로 플레이 영역에 내려놓습니다. 그럴 수 없다면, 이렇게 버려진 각 [[인헤리터]] 하수인을 시작 플레이어와 교전 중인 채로 플레이 영역에 내려놓습니다."},{"id":"30031","name":"보라","en":"* Bora","type":"minion","enc":true,"set":"The Inheritors","unique":true,"hp":5,"atk":1,"sch":3,"boost":2,"tr":["INHERITOR"],"traits":["인헤리터"],"text":"각 [[인헤리터]] 하수인은 가속 아이콘([acceleration]) 1개를 얻습니다.\n<b>공개될 때</b>: [[웹 워리어]] 캐릭터가 플레이 영역에 있다면, 각 음모에 위협을 1만큼 놓습니다."},{"id":"30032","name":"브릭스","en":"* Brix","type":"minion","enc":true,"set":"The Inheritors","unique":true,"hp":5,"atk":2,"sch":1,"boost":2,"tr":["INHERITOR"],"traits":["인헤리터"],"text":"각 [[인헤리터]] 하수인은 순찰을 얻습니다.\n<b>공개될 때</b>: [[웹 워리어]] 캐릭터가 플레이 영역에 있다면, 주요 음모에 위협을 2만큼 놓습니다."},{"id":"30033","name":"데이모스","en":"* Daemos","type":"minion","enc":true,"set":"The Inheritors","unique":true,"hp":6,"atk":3,"sch":1,"boost":2,"tr":["INHERITOR"],"traits":["인헤리터"],"text":"각 [[인헤리터]] 하수인은 견고를 얻습니다.\n<b>공개될 때</b>: [[웹 워리어]] 캐릭터가 플레이 영역에 있다면, 당신이 조종하는 캐릭터 하나를 기절시킵니다."},{"id":"30034","name":"제닉스","en":"* Jennix","type":"minion","enc":true,"set":"The Inheritors","unique":true,"hp":6,"atk":2,"sch":2,"boost":2,"tr":["INHERITOR"],"traits":["인헤리터"],"text":"각 [[인헤리터]] 하수인은 경호를 얻습니다.\n<b>공개될 때</b>: [[웹 워리어]] 캐릭터가 플레이 영역에 있다면, 제닉스에게 강인함 상태 카드를 줍니다."},{"id":"30035","name":"카른","en":"* Karn","type":"minion","enc":true,"set":"The Inheritors","unique":true,"hp":5,"atk":3,"sch":1,"boost":2,"tr":["INHERITOR"],"traits":["인헤리터"],"text":"각 [[인헤리터]] 하수인의 공격은 압살과 관통을 얻습니다.\n<b>공개될 때</b>: [[웹 워리어]] 캐릭터가 플레이 영역에 있다면, 당신이 조종하는 업그레이드나 지원 1장을 버립니다."},{"id":"30036","name":"몰런","en":"* Morlun","type":"minion","enc":true,"set":"The Inheritors","unique":true,"hp":5,"atk":2,"sch":2,"boost":2,"tr":["ELITE","INHERITOR"],"traits":["간부","인헤리터"],"text":"각 [[인헤리터]] 하수인은 공격 +1을 받습니다.\n<b>공개될 때</b>: [[웹 워리어]] 캐릭터가 플레이 영역에 있다면, 피해 2점을 입습니다."},{"id":"30037","name":"솔루스","en":"* Solus","type":"minion","enc":true,"set":"The Inheritors","unique":true,"hp":7,"atk":3,"sch":2,"boost":3,"tr":["ELITE","INHERITOR"],"traits":["간부","인헤리터"],"text":"각 [[인헤리터]] 하수인은 악당을 얻습니다.\n<b>공개될 때</b>: [[웹 워리어]] 캐릭터가 플레이 영역에 있다면, 솔루스에게 강화 카드 1장을 뒷면으로 줍니다."},{"id":"30038","name":"버나","en":"* Verna","type":"minion","enc":true,"set":"The Inheritors","unique":true,"hp":6,"atk":1,"sch":1,"boost":2,"tr":["ELITE","INHERITOR"],"traits":["간부","인헤리터"],"text":"각 [[인헤리터]] 하수인은 반격 1을 얻습니다.\n<b>공개될 때</b>: [[웹 워리어]] 캐릭터가 플레이 영역에 있다면, 당신이 조종하는 각 캐릭터에게 피해 1점을 입힙니다."}]});
